368  static gboolean
   369  fu_coswid_firmware_parse_payload(FuCoswidFirmware *self,
   370                                   cbor_item_t *item,
   371                                   gpointer user_data,
   372                                   GError **error)
   373  {
   374          struct cbor_pair *pairs = cbor_map_handle(item);
   375          for (gsize i = 0; i < cbor_map_size(item); i++) {
   376                  FuCoswidTag tag_id = cbor_get_uint8(pairs[i].key);
   377                  if (tag_id == FU_COSWID_TAG_FILE) {
   378                          if (!fu_coswid_firmware_parse_one_or_many(self,
   379                                                                    pairs[i].value,
   380                                                                    fu_coswid_firmware_parse_file,
   381                                                                    NULL, /* user_data */
   382                                                                    error))
   383                                  return FALSE;
   384                  } else if (tag_id == FU_COSWID_TAG_DIRECTORY) {
   385                          if (!fu_coswid_firmware_parse_one_or_many(
   386                                  self,
   387                                  pairs[i].value,
   388                                  fu_coswid_firmware_parse_directory,
   389                                  NULL, /* user_data */
   390                                  error))
   391                                  return FALSE;
   392                  } else {
   393                          g_debug("unhandled tag %s from %s",
   394                                  fu_coswid_tag_to_string(tag_id),
   395                                  fu_coswid_tag_to_string(FU_COSWID_TAG_PAYLOAD));
   396                  }
   397          }
   398
   399          /* success */
   400          return TRUE;
   401  }
