   574  static gchar *
   575  fu_coswid_firmware_get_checksum(FuFirmware *firmware, GChecksumType csum_kind, GError **error)
   576  {
   577          FuCoswidFirmware *self = FU_COSWID_FIRMWARE(firmware);
   578          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   579          FuCoswidHashAlg alg_id = FU_COSWID_HASH_ALG_UNKNOWN;
   580          struct {
   581                  GChecksumType kind;
   582                  FuCoswidHashAlg alg_id;
   583          } csum_kinds[] = {{G_CHECKSUM_SHA256, FU_COSWID_HASH_ALG_SHA256},
   584                            {G_CHECKSUM_SHA384, FU_COSWID_HASH_ALG_SHA384},
   585                            {G_CHECKSUM_SHA512, FU_COSWID_HASH_ALG_SHA512},
   586                            {0, FU_COSWID_HASH_ALG_UNKNOWN}};
   587
   588          /* convert to FuCoswidHashAlg */
   589          for (guint i = 0; csum_kinds[i].kind != 0; i++) {
   590                  if (csum_kinds[i].kind == csum_kind) {
   591                          alg_id = csum_kinds[i].alg_id;
   592                          break;
   593                  }
   594          }
   595          if (alg_id == FU_COSWID_HASH_ALG_UNKNOWN) {
   596                  g_set_error(error,
   597                              FWUPD_ERROR,
   598                              FWUPD_ERROR_NOT_SUPPORTED,
   599                              "cannot convert %s",
   600                              fwupd_checksum_type_to_string_display(csum_kind));
   601                  return NULL;
   602          }
   603
   604          /* find the correct hash kind */
   605          for (guint i = 0; i < priv->payloads->len; i++) {
   606                  FuCoswidFirmwarePayload *payload = g_ptr_array_index(priv->payloads, i);
   607                  for (guint j = 0; j < payload->hashes->len; j++) {
   608                          FuCoswidFirmwareHash *hash = g_ptr_array_index(payload->hashes, j);
   609                          if (hash->alg_id == alg_id)
   610                                  return fu_byte_array_to_string(hash->value);
   611                  }
   612          }
   613          g_set_error(error,
   614                      FWUPD_ERROR,
   615                      FWUPD_ERROR_NOT_SUPPORTED,
   616                      "no hash kind %s",
   617                      fwupd_checksum_type_to_string_display(csum_kind));
   618          return NULL;
   619  }
