   700          if (!cbor_array_push(item_hash, item_hash_alg_id))
   701                  g_critical("failed to push to definite array");
   702          if (!cbor_array_push(item_hash, item_hash_value))
   703                  g_critical("failed to push to definite array");
   704          if (!cbor_array_push(root, item_hash))
   705                  g_critical("failed to push to indefinite array");
